{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table vahdam_db.maplemonk.vahdam_in_3p_finevents_actuals as with sku_asin as ( select SKU, ASIN from ( select SKU, case when sku = \'Uncommingled.MSKU.1614859309584\' then \'B08Y1FH4ZP\' else ASIN end as ASIN, row_number() over (partition by SKU order by ASIN) rw from (select distinct SKU, ASIN from vahdam_db.maplemonk.ASP_IN_GET_FLAT_FILE_ALL_ORDERS_DATA_BY_LAST_UPDATE_GENERAL where year(\"purchase-date\"::date) >= \'2023\' and sku is not null) ) where rw = 1 ), ship as ( select POSTEDDATE::date as day, SELLERSKU, sum(ifnull(PRINCIPAL,0)) + sum(ifnull(SHIPPINGCHARGE,0)) + sum(ifnull(GIFTWRAP,0)) + sum(ifnull(PROMOTION,0)) + sum(ifnull(GIFTWRAPCHARGEBACK,0)) + sum(ifnull(SHIPPINGCHARGEBACK,0)) + sum(ifnull(PAYMENTMETHODFEE,0)) as sales_product_net, sum(ifnull(QUANTITY,0)) as qty, sum(ifnull(COMMISSION,0)) + sum(ifnull(FIXEDCLOSINGFEE,0)) + sum(ifnull(VARIABLECLOSINGFEE,0)) + sum(ifnull(GIFTWRAPCOMMISSION,0)) + sum(ifnull(TECHNOLOGYFEE,0)) as commission, sum(ifnull(FBAPERUNITFULFILLMENTFEE,0)) + sum(ifnull(FBAWEIGHTBASEDFEE,0)) + sum(ifnull(SHIPPINGHB,0)) as last_mile_direct from vahdam_db.maplemonk.vahdam_IN_shipment_event_list where lower(MarketplaceName)=\'amazon.in\' group by 1,2 ), refund as ( select POSTEDDATE::date as day, SELLERSKU, sum(ifnull(PRINCIPAL,0)) + sum(ifnull(SHIPPINGCHARGE,0)) + sum(ifnull(GIFTWRAP,0)) + sum(ifnull(REFUND_PROMOTION,0)) + sum(ifnull(GIFTWRAPCHARGEBACK,0)) + sum(ifnull(SHIPPINGCHARGEBACK,0)) + sum(ifnull(RETURNSHIPPING,0)) + sum(ifnull(GOODWILL,0)) as sales_product_net, -1 * sum(ifnull(QUANTITY,0)) as qty, sum(ifnull(COMMISSION,0)) + sum(ifnull(REFUNDCOMMISSION,0)) + sum(ifnull(VARIABLECLOSINGFEE,0)) + sum(ifnull(FIXEDCLOSINGFEE,0)) + sum(ifnull(GIFTWRAPCOMMISSION,0)) as commission, 0 as last_mile_direct from vahdam_db.maplemonk.vahdam_IN_refund_event_list where lower(MarketplaceName)=\'amazon.in\' group by 1,2 ), adj as ( select PostedDate::date as day, SellerSKU, sum(ifnull(Compensated_Clawback_Total_Amount,0)) + sum(ifnull(WAREHOUSE_DAMAGE_Total_Amount,0)) + sum(ifnull(REVERSAL_REIMBURSEMENT_Total_Amount,0)) + sum(ifnull(WAREHOUSE_LOST_Total_Amount,0)) + sum(ifnull(WAREHOUSE_LOST_MANUAL_Total_Amount,0)) + sum(ifnull(WAREHOUSE_DAMAGE_EXCEPTION_Total_Amount,0)) + sum(ifnull(FREE_REPLACEMENT_REFUND_ITEMS_Total_Amount,0)) + sum(ifnull(MISSING_FROM_INBOUND_Total_Amount,0)) + sum(ifnull(MISSING_FROM_INBOUND_CLAWBACK_Total_Amount,0)) + sum(ifnull(RE_EVALUATION_Total_Amount,0)) + sum(ifnull(MULTICHANNEL_ORDER_LOST_Total_Amount,0)) + sum(ifnull(PAYMENT_RETRACTION_ITEMS_Total_Amount,0)) + sum(ifnull(LostOrDamagedReimbursement_Total_Amount,0)) + sum(ifnull(OTHER_ADJUSTMENT_Total_Amount,0)) as other_sales from vahdam_db.maplemonk.vahdam_IN_adjustment_event_list where Currency = \'INR\' group by 1,2 ), direct_sku as ( select coalesce(s.day,r.day) as day, coalesce(s.SELLERSKU,r.SELLERSKU) as sku, ifnull(s.sales_product_net,0) + ifnull(r.sales_product_net,0) as sales_product_net, ifnull(s.qty,0) + ifnull(r.qty,0) as units, ifnull(s.commission,0) + ifnull(r.commission,0) as commission, ifnull(s.last_mile_direct,0) + ifnull(r.last_mile_direct,0) as last_mile_direct from ship s full outer join refund r on s.day = r.day and lower(s.SELLERSKU) = lower(r.SELLERSKU) ), direct_asin as ( select d.day, sa.ASIN as asin, sum(d.sales_product_net) as sales_product_net, sum(d.units) as units, sum(d.commission) as commission, sum(d.last_mile_direct) as last_mile_direct from direct_sku d left join sku_asin sa on lower(d.sku) = lower(sa.SKU) group by 1,2 ), adj_asin as ( select a.day, sa.ASIN as asin, sum(a.other_sales) as other_sales from adj a left join sku_asin sa on lower(a.SellerSKU) = lower(sa.SKU) group by 1,2 ), svc_day as ( select Date as day, sum(case when Fee_Type in (\'FBADisposalFee\',\'FBARemovalFee\',\'LabelingFee\',\'FBAInboundDefectFee\',\'MFNPostageFee\',\'FBAWeightBasedFee\',\'FBAPerUnitFulfillmentFee\') then Amount else 0 end) as lastmile_pool, sum(case when Fee_Type in (\'DealParticipationFee\',\'DealPerformanceFee\',\'CouponParticipationFee\',\'CouponPerformanceFee\',\'VineFee\',\'Subscription\') then Amount else 0 end) as pm_pool, sum(case when Fee_Type = \'AmazonUpstreamProcessingFee\' then Amount else 0 end) as storage_daily_pool from vahdam_db.maplemonk.vahdam_in_service_fees where Currency = \'INR\' group by 1 ), storage_month_raw as ( select date_trunc(\'month\', Date) as m, sum(Amount) as amt from vahdam_db.maplemonk.vahdam_in_service_fees where Currency = \'INR\' and Fee_Type in (\'FBAStorageFee\',\'FBALongTermStorageFee\',\'STARStorageFee\') group by 1 ), month_spine as (select distinct date_trunc(\'month\', day) as m from direct_asin), storage_used as ( select s.m, coalesce(nullif(cur.amt,0), prev.amt) as storage_amt_used from month_spine s left join storage_month_raw cur on cur.m = s.m left join storage_month_raw prev on prev.m = dateadd(month,-1,s.m) ), day_tot as (select day, sum(sales_product_net) as tot_sales_net from direct_asin group by 1) select da.day, \'Amazon_3P\' as channel, \'IN\' as geo, da.asin, da.units, da.sales_product_net, ifnull(aj.other_sales,0) as other_sales, da.sales_product_net + ifnull(aj.other_sales,0) as sales_net, da.commission, da.last_mile_direct + ifnull(sv.lastmile_pool,0) * div0(da.sales_product_net, dt.tot_sales_net) as last_mile, ifnull(su.storage_amt_used,0) * div0(da.sales_product_net, dt.tot_sales_net) / day(last_day(da.day)) + ifnull(sv.storage_daily_pool,0) * div0(da.sales_product_net, dt.tot_sales_net) as storage, ifnull(sv.pm_pool,0) * div0(da.sales_product_net, dt.tot_sales_net) as pm_fees from direct_asin da left join adj_asin aj on aj.day = da.day and aj.asin = da.asin left join day_tot dt on dt.day = da.day left join svc_day sv on sv.day = da.day left join storage_used su on su.m = date_trunc(\'month\', da.day); create or replace table vahdam_db.maplemonk.vahdam_amazon_pnl_finevents_in_3p as with asin_map_unpivot as ( select trim(asin) as asin, src, BRAND as brand, \"Common SKU ID\" as common_sku_id, \"Common SKU Description\" as common_sku_description, CATEGORY as category, \"Sub-category\" as sub_category, \"Type-3\" as amz_category from vahdam_db.maplemonk.VAHDAM_FY27_INPUTS_PRODUCT_MAPPING unpivot (asin for src in ( \"Amazon USA\",\"Amazon CA\",\"Amazon DE\",\"Amazon ES\",\"Amazon FR\",\"Amazon IT\", \"Amazon UK\",\"Amazon UAE\",\"Amazon AUS\",\"Amazon JP\",\"Amazon SG\",\"Amazon India\", \"Amazon US 1P\",\"Amazon UK 1P\",\"Amazon EU 1P\",\"Amazon CA 1P\",\"Amazon India 1P\")) where asin is not null and trim(asin) <> \'\' ), asin_geo_map as ( select asin, brand, common_sku_id, common_sku_description, category, sub_category, amz_category, case when src ilike \'%1P\' then \'Amazon_1P\' else \'Amazon_3P\' end as channel, case when upper(src)=\'AMAZON USA\' then \'USA\' when upper(src)=\'AMAZON US 1P\' then \'USA\' when upper(src)=\'AMAZON INDIA\' then \'IN\' when upper(src)=\'AMAZON INDIA 1P\' then \'IN\' else upper(replace(replace(src,\'Amazon \',\'\'),\' 1P\',\'\')) end as geo from asin_map_unpivot where upper(src) <> \'AMAZON EU 1P\' ), asin_geo_map_dedup as ( select asin, channel, geo, any_value(brand) brand, any_value(common_sku_id) common_sku_id, any_value(common_sku_description) common_sku_description, any_value(category) category, any_value(sub_category) sub_category, any_value(amz_category) amz_category from asin_geo_map group by asin, channel, geo ), cogs_sheet as ( select trim(MATERIAL) as common_sku_id, try_to_decimal(replace(COGS,\',\',\'\'),30,5) as cogs_per_unit_inr from vahdam_db.maplemonk.VAHDAM_FY27_INPUTS_COGS_SHEET where MATERIAL is not null ), india_ob as ( select trim(ASIN) as asin, avg(try_to_decimal(replace(OB_PU,\',\',\'\'),30,5)) as ob_per_unit from vahdam_db.maplemonk.FY27_INPUTS_AMAZON_INDIA_COSTS where ASIN is not null and try_to_decimal(replace(OB_PU,\',\',\'\'),30,5) is not null group by 1 ), budget_raw as ( select upper(GEOGRAPHY) as geo, case when upper(PLATFORM) like \'%1P%\' then \'Amazon_1P\' when upper(PLATFORM) like \'%3P%\' then \'Amazon_3P\' else PLATFORM end as channel, try_to_date(\"MONTH\",\'DD-Mon-YY\') as month_start, try_to_decimal(replace(FX,\',\',\'\'),30,5) as fx from vahdam_db.maplemonk.VAHDAM_BUDGET_AMAZON_3P___1P_BUDGET ), fx_map as (select geo, month_start, max(fx) fx from budget_raw where fx is not null and month_start is not null group by 1,2), pm_src as ( select DATE as day, coalesce(ASIN, regexp_substr(CAMPAIGNNAME,\'B0[A-Z0-9]{8}\')) as asin, SPEND as spend from vahdam_db.maplemonk.amazonads_in_marketing where DATE is not null and SPEND is not null ), pm_total_day as (select day, sum(spend) as tot_spend from pm_src group by 1), pm_direct as (select day, asin, sum(spend) as spend from pm_src where asin is not null group by 1,2), tool_cost_monthly as ( select try_to_date(MONTH,\'MM-DD-YYYY\') month_start, sum(try_to_decimal(replace(\"Spend(INR)\",\',\',\'\'),30,5)) tool_cost_total_inr from vahdam_db.maplemonk.fy27_inputs_tool_cost where upper(BUSINESS)=\'AMAZON\' and try_to_date(MONTH,\'MM-DD-YYYY\') is not null group by 1 ), global_tool_denom as ( select date_trunc(\'month\',sm.DAY) month_start, sum(sm.SALES * coalesce(fxm.fx, iff(upper(sm.GEO) in (\'IN\',\'INDIA\'),1,null))) global_sales_inr from vahdam_db.maplemonk.VAHDAM_AMAZON_SALES_MARKETING sm left join fx_map fxm on fxm.geo=upper(sm.GEO) and fxm.month_start=date_trunc(\'month\',sm.DAY) where upper(sm.MARKETPLACE)=\'AMAZON_3P\' group by 1 ), fe as (select * from vahdam_db.maplemonk.vahdam_in_3p_finevents_actuals), fe_sales as (select day, asin, sum(sales_net) as asin_sales from fe group by 1,2), fe_day_tot as (select day, sum(sales_net) as day_sales from fe group by 1), pm_matched_day as ( select f.day, sum(pd.spend) as matched_spend from fe_sales f join pm_direct pd on pd.day=f.day and pd.asin=f.asin group by 1 ), pm_final as ( select f.day, f.asin, ifnull(pd.spend,0) + (ifnull(ptd.tot_spend,0) - ifnull(pmd.matched_spend,0)) * div0(f.asin_sales, dt.day_sales) as pm_spend_actual_local, 0 as google_spend_actual_local from fe_sales f left join pm_direct pd on pd.day=f.day and pd.asin=f.asin left join pm_total_day ptd on ptd.day=f.day left join pm_matched_day pmd on pmd.day=f.day left join fe_day_tot dt on dt.day=f.day ), asin_resolved as ( select u.day,u.channel,u.geo,u.asin, m.brand,m.common_sku_id,m.common_sku_description,m.category,m.sub_category,m.amz_category from fe u left join asin_geo_map_dedup m on m.asin=u.asin and m.channel=u.channel and m.geo=u.geo ), pass1 as ( select u.day,u.channel,u.geo,u.asin, ar.brand,ar.common_sku_id,ar.common_sku_description,ar.category,ar.sub_category,ar.amz_category, date_trunc(\'month\',u.day) month_start, 1 as fx_inr, u.units as qty_actual, u.sales_net as sales_actual_local, u.other_sales, u.commission as commission_signed, u.last_mile as last_mile_signed, u.storage as storage_signed, u.pm_fees as pm_fees_signed, pa.pm_spend_actual_local, pa.google_spend_actual_local, cs.cogs_per_unit_inr as cogs_per_unit_inr_p1, iob.ob_per_unit as outbound_per_unit_local_p1 from fe u left join asin_resolved ar on ar.day=u.day and ar.channel=u.channel and ar.geo=u.geo and ar.asin=u.asin left join pm_final pa on pa.day=u.day and pa.asin=u.asin left join cogs_sheet cs on cs.common_sku_id=ar.common_sku_id left join india_ob iob on iob.asin=u.asin ), actuals_pct as ( select month_start, case when sum(case when cogs_per_unit_inr_p1 is not null and qty_actual is not null then sales_actual_local end) > 0 then sum(case when cogs_per_unit_inr_p1 is not null and qty_actual is not null then qty_actual*cogs_per_unit_inr_p1 end) / nullif(sum(case when cogs_per_unit_inr_p1 is not null and qty_actual is not null then sales_actual_local end),0) end as cogs_pct, case when sum(case when outbound_per_unit_local_p1 is not null and qty_actual is not null then sales_actual_local end) > 0 then sum(case when outbound_per_unit_local_p1 is not null and qty_actual is not null then qty_actual*outbound_per_unit_local_p1 end) / nullif(sum(case when outbound_per_unit_local_p1 is not null and qty_actual is not null then sales_actual_local end),0) end as outbound_pct from pass1 group by 1 ), pass1b as ( select p.* replace ( coalesce(p.cogs_per_unit_inr_p1, p.sales_actual_local*ap.cogs_pct/nullif(p.qty_actual,0)) as cogs_per_unit_inr_p1, coalesce(p.outbound_per_unit_local_p1, p.sales_actual_local*ap.outbound_pct/nullif(p.qty_actual,0)) as outbound_per_unit_local_p1 ) from pass1 p left join actuals_pct ap on ap.month_start=p.month_start ) select p.day, p.channel, p.geo, p.asin, p.brand, p.common_sku_id, p.common_sku_description, p.category, p.sub_category, p.amz_category as AMZ_Category, \'INR\' as currency_local, p.fx_inr, p.month_start, p.qty_actual, p.other_sales, p.sales_actual_local as sales_actual_local, p.qty_actual * p.cogs_per_unit_inr_p1 as cogs_actual_local, 0 as additional_duty_actual_local, -1 * p.commission_signed as commission_actual_local, p.qty_actual * p.outbound_per_unit_local_p1 as outbound_actual_local, 0 as three_pl_actual_local, -1 * p.storage_signed as storage_actual_local, -1 * p.last_mile_signed as last_mile_actual_local, p.pm_spend_actual_local, p.google_spend_actual_local, -1 * p.pm_fees_signed as amazon_marketing_fees_local, case when p.sales_actual_local is not null and gtd.global_sales_inr > 0 and tcm.tool_cost_total_inr is not null then tcm.tool_cost_total_inr * (p.sales_actual_local*p.fx_inr)/gtd.global_sales_inr else 0 end / nullif(p.fx_inr,0) as tool_cost_actual_local, ifnull(p.sales_actual_local,0) - ifnull(p.qty_actual * p.cogs_per_unit_inr_p1,0) - ifnull(-1*p.commission_signed,0) - ifnull(p.qty_actual * p.outbound_per_unit_local_p1,0) - ifnull(-1*p.storage_signed,0) - ifnull(-1*p.last_mile_signed,0) as cm1_actual_local, ( ifnull(p.sales_actual_local,0) - ifnull(p.qty_actual * p.cogs_per_unit_inr_p1,0) - ifnull(-1*p.commission_signed,0) - ifnull(p.qty_actual * p.outbound_per_unit_local_p1,0) - ifnull(-1*p.storage_signed,0) - ifnull(-1*p.last_mile_signed,0) ) - ifnull(p.pm_spend_actual_local,0) - ifnull(p.google_spend_actual_local,0) - ifnull(-1*p.pm_fees_signed,0) - ifnull(case when p.sales_actual_local is not null and gtd.global_sales_inr>0 and tcm.tool_cost_total_inr is not null then tcm.tool_cost_total_inr*(p.sales_actual_local*p.fx_inr)/gtd.global_sales_inr else 0 end / nullif(p.fx_inr,0),0) as cm2_actual_local, 0 as qty_budget, 0 as sales_budget_local, 0 as cogs_budget_local, 0 as additional_duty_budget_local, 0 as commission_budget_local, 0 as outbound_budget_local, 0 as three_pl_budget_local, 0 as storage_budget_local, 0 as last_mile_budget_local, 0 as pm_spend_budget_local, 0 as cm1_budget_local, 0 as cm2_budget_local from pass1b p left join tool_cost_monthly tcm on tcm.month_start=p.month_start left join global_tool_denom gtd on gtd.month_start=p.month_start order by p.day desc;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from VAHDAM_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
